public function update(UpdateKbArticleRequest $request, ItKbArticle $article)
{
    $user = $request->user();

    // Slug stays stable across edits (a title tweak shouldn't churn a
    // published article's URL); it is only ever generated at create time.
    $data = $request->validated();
    try {
        $this->lifecycle->update($article, $user, $data);
    } catch (DomainException $exception) {
        return redirect()->back()->with('error', $exception->getMessage());
    }

    return redirect()->back()->with('success', 'Article updated.');
}

public function update(ItKbArticle $article, User $actor, array $data): ItKbArticle
{
    return DB::transaction(function () use ($article, $actor, $data): ItKbArticle {
        $locked = $this->lockArticle($article);
        $this->guardActor($actor);
        $data = $this->normaliseOptions($locked, $actor, $data);
        $locked->fill(Arr::except($data, ['status', 'slug']));
        $changedFields = array_keys($locked->getDirty());
        if ($changedFields === []) {
            return $locked;
        }
        $locked->save();

        AuditLogger::logOrFail('it.knowledge.updated', $locked, [
            'actor_id' => $actor->id,
            'changed_fields' => $changedFields,
            'application_scope' => 'single_application',
        ]);

        return $locked->refresh();
    });
}

public function authorize(): bool
{
    $user = $this->user();

    return (bool) ($user && $user->canDo('it.manage'));
}

